-- Idempotent 2026 season competitor fields used by LOC drafts.
create temporary table loc_catalog_seed (
  sport_key text not null,
  edition_name text not null,
  season_year integer not null,
  edition_status text not null,
  source_url text not null,
  competitor_name text not null,
  eligible boolean not null,
  primary key (sport_key, edition_name, competitor_name)
) on commit drop;


select s.id, d.edition_name, d.season_year, d.edition_status,
       jsonb_build_object('catalog_source', d.source_url, 'snapshot_date', '2026-09-28')
from (select distinct sport_key, edition_name, season_year, edition_status, source_url from loc_catalog_seed) d
join public.sports s on s.key = d.sport_key
on conflict (sport_id, season_year, name) do update
set status = excluded.status, metadata = public.competition_editions.metadata || excluded.metadata,
    updated_at = now();

select distinct s.id, seed.competitor_name, true,
       jsonb_build_object('catalog_source', seed.source_url, 'snapshot_date', '2026-09-28')
from loc_catalog_seed seed
join public.sports s on s.key = seed.sport_key
on conflict (sport_id, name) do update
set active = true, metadata = public.competitors.metadata || excluded.metadata, updated_at = now();

select edition.id, competitor.id, seed.eligible,
       jsonb_build_object('catalog_source', seed.source_url, 'snapshot_date', '2026-09-28')
from loc_catalog_seed seed
join public.sports sport on sport.key = seed.sport_key
join public.competition_editions edition
  on edition.sport_id = sport.id and edition.name = seed.edition_name and edition.season_year = seed.season_year
join public.competitors competitor
  on competitor.sport_id = sport.id and competitor.name = seed.competitor_name
on conflict (competition_edition_id, competitor_id) do update
set eligible = excluded.eligible,
    metadata = public.competition_entries.metadata || excluded.metadata,
    updated_at = now();

do $$
declare
  expected_count integer;
  actual_count integer;
  sport_key text;
begin
  for sport_key, expected_count in
    select * from (values
      ('nba', 30), ('nfl', 32), ('mlb', 30), ('nhl', 32),
      ('ncaa_football', 266), ('ncaa_basketball', 365),
      ('uefa_champions_league', 36), ('nascar', 15), ('masters_tournament', 91)
    ) as expected(sport_key, expected_count)
  loop
    select count(*) into actual_count
    from public.competition_entries entry
    join public.competition_editions edition on edition.id = entry.competition_edition_id
    join public.sports sport on sport.id = edition.sport_id
    where sport.key = sport_key and entry.eligible;

    if actual_count <> expected_count then
      raise exception 'Catalog count mismatch for %: expected %, got %', sport_key, expected_count, actual_count;
    end if;
  end loop;
end;
$$;

